import React from 'react';

function Book(props)
{
    return(
        <div style= {{border: "1px solid grey", margin: "10px", color: "Red", padding:"20px", textAlign: "center"}}>
            <img src={props.image} style={{width: "100%", height:"100px", zIndex: "1", backgroundSize: "cover", position: ""}}/>
            <h2 style={{zIndex: "999"}}>{props.title}</h2>
            <p style={{zIndex: "999"}}>{props.author}</p>
            <p style={{zIndex: "999"}}>${props.price}</p>
        </div>
    );
}
export default Book;
